import { FOOD_EXTRAS } from './foodExtras';
import { CIQUAL_FILL } from './ciqualFill';

type RawRecord = Record<string, RawNutrientValue>;
type ImportedFood = {
  id: number;
  name: string;
  category: string;
  alim_code?: number;
  source_name: string;
  source?: string;
  values: Partial<Record<NutrientKey, number>>;
  raw: RawRecord;
};

function importedFood(item: ImportedFood): Food {
  return {
    id: `primal-${item.id}`,
    source: 'core',
    ciqualCode: item.alim_code,
    ciqualRaw: { ...item.raw, ...(item.alim_code !== undefined ? { alim_code: item.alim_code } : {}), sourceName: item.source_name, source: item.source ?? 'Ciqual 2025', category: item.category, reference: '100 g' },
    name: item.name,
    category: item.category,
    portionLabel: '100 g',
    portionGrams: 100,
    per100: item.values,
  };
}

